```typescript
// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { axe, toHaveNoViolations } from 'jest-axe';

expect.extend(toHaveNoViolations);

// Mock the contexts - boring but necessary
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockItems = [
  { id: '1', name: 'Hiro Protagonist Action Figure', price: 29.99 },
  { id: '2', name: 'Smartwheels Upgrade Kit', price: 149.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 179.98, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout - The Fun Way', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-420-BLAZEIT' });
  });

  // HAPPY PATH - Full send through checkout
  it('completes entire checkout flow without wiping out', async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    render(<Checkout onComplete={onComplete} />);

    // Shipping - fill it fast
    await user.type(screen.getByLabelText(/street address/i), '123 Metaverse Lane');
    await user.type(screen.getByLabelText(/city/i), 'Los Angeles');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment - throw my card at it
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Y.T. Courier');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review - slam that order button
    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByRole('status')).toHaveTextContent(/order confirmed/i);
    });
    expect(onComplete).toHaveBeenCalledWith('ORD-420-BLAZEIT');
  });

  // VALIDATION - Let's see what explodes
  it('shows shipping errors when you try to skip fields', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
    expect(screen.getByText(/city is required/i)).toBeInTheDocument();
    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });

  it('rejects bogus card numbers', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    // Speed through shipping
    await user.type(screen.getByLabelText(/street/i), '123 Test');
    await user.type(screen.getByLabelText(/city/i), 'LA');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue/i }));

    await user.type(screen.getByLabelText(/card number/i), '1234');
    await user.click(screen.getByRole('button', { name: /review/i }));

    expect(screen.getByText(/valid 16-digit card/i)).toBeInTheDocument();
  });

  // LOADING STATE - Patience is for adults
  it('disables buttons and shows loading during payment', async () => {
    mockProcessPayment.mockImplementation(() => new Promise(() => {})); // Never resolves
    const user = userEvent.setup();
    render(<Checkout />);

    // Speedrun to review
    // ...fill forms...

    await user.click(screen.getByRole('button', { name: /place order/i }));

    expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
  });

  // ERROR RECOVERY - When you eat pavement
  it('displays payment error and allows retry', async () => {
    mockProcessPayment.mockRejectedValueOnce(new Error('Card declined, poser'));
    const user = userEvent.setup();
    render(<Checkout />);

    // ...navigate to review...
    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });

    // Try again - we don't give up
    mockProcessPayment.mockResolvedValueOnce({ orderId: 'RETRY-WIN' });
    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
    });
  });

  // EDGE CASES - The weird stuff
  it('shows empty cart message when no items', () => {
    vi.mocked(require('./CartContext').useCart).mockReturnValue({ items: [], total: 0 });
    render(<Checkout />);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });

  // ACCESSIBILITY - Even couriers need ramps
  it('has no accessibility violations on shipping step', async () => {
    const { container } = render(<Checkout />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it('announces errors to screen readers', async () => {
    const user = userEvent.setup();
    render(<Checkout />);
    await user.click(screen.getByRole('button', { name: /continue/i }));

    const alerts = screen.getAllByRole('alert');
    expect(alerts.length).toBeGreaterThan(0);
  });
});
